package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="shared_expenses") @Data @NoArgsConstructor @AllArgsConstructor @Builder
public class SharedExpense { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="group_id",nullable=false) private SharedExpenseGroup group; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; @Column(nullable=false,length=500) private String description; private String category; @Column(nullable=false) private LocalDate expenseDate; @Column(nullable=false,precision=19,scale=2) private BigDecimal totalAmount; @Enumerated(EnumType.STRING) @Column(nullable=false) private SharedSplitType splitType; @Builder.Default @Column(nullable=false) private Boolean reversed=false; @Builder.Default @Column(nullable=false,updatable=false) private LocalDateTime createdAt=LocalDateTime.now(); @Builder.Default @Column(nullable=false) private LocalDateTime updatedAt=LocalDateTime.now(); }
